// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(1, "", ""); }
    function testRegression_property() public {
        // owner already has totalSupply = 1 * 10^0 = 1
        // We need to mint more to get balance of 10 for owner
        // Use mintToken to give owner 9 more (total owner balance = 10)
        c.mintToken(address(this), 9);
        // Now owner (this contract) has balance 10, totalSupply = 10
        // Try to burn(10): reference succeeds and totalSupply becomes 0, bug reverts
        bool ok;
        try c.burn(10) { ok = true; } catch { ok = false; }
        assertTrue(ok == true, "burn should succeed");
        // After burn, totalSupply should be 0 in reference; bug never changes it
        // The assertion below fails on bug because bug reverts and totalSupply remains 10
        assertTrue(c.totalSupply() == 0, "totalSupply after burn");
    }
}

