// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Initial state: totalSupply = 0, owner = address(this)
        // Mint 100 tokens to owner (address(this))
        c.mintToken(address(this), 100);
        // Now totalSupply in reference = 100, in bug = -100
        // Burn 50 tokens (requires balance >= 50 and totalSupply >= 50)
        // Bug: totalSupply was -100, so burn's require(balanceOf[msg.sender] >= _value) passes
        // but the bug subtracts from totalSupply making it -150
        // We can detect the difference by trying to burn again after that:
        // Reference allows a second burn, bug reverts because totalSupply underflows
        c.burn(50);
        // Now reference totalSupply = 50, bug totalSupply = -150
        // Try a second burn of 1 token:
        bool ok;
        try c.burn(1) { ok = true; } catch { ok = false; }
        // Reference: totalSupply 50 >= 1, balance 50 >= 1 => succeeds (ok = true)
        // Bug: totalSupply -150, and require(balanceOf[msg.sender] >= _value) still passes
        // but totalSupply -= _value would underflow (since totalSupply is uint256)
        // Actually totalSupply is uint256, so -150 wraps to a large number, no underflow
        // The bug is totalSupply -= mintedAmount makes totalSupply decrease on mint
        // Let's make a cleaner scenario:
        // After initial deploy totalSupply = 0
        // Mint 10 tokens => reference totalSupply = 10, bug totalSupply = -10 (wraps to 2^256 - 10)
        // Burn 1 token => reference totalSupply = 9, bug totalSupply = 2^256 - 10 - 1 (huge)
        // The two diverge: reference totalSupply is small, bug totalSupply is huge
        // Assert: reference totalSupply < 100, bug totalSupply > 2^255
        // This fails because we need a fresh contract for clean assertion.
        // Let's restart logic fresh:
        c = new C(0, 0, 0);
        c.mintToken(address(this), 1);
        c.burn(1);
        uint256 after = c.totalSupply();
        // Reference: mint 1 => totalSupply=1, burn 1 => totalSupply=0
        // Bug: mint 1 => totalSupply=2^256-1, burn 1 => totalSupply=2^256-2
        assertTrue(after != 0, "totalSupply should be 0, but bug gives huge value");
    }
}

