import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // owner is the contract deployer (address(this))
        // mint 100 tokens to owner
        c.mintToken(address(this), 100);
        // burn 150 tokens (greater than balance in reference, but not in bug)
        // In reference, balanceOf[owner]=100, totalSupply=100, burn(150) should revert.
        // In bug, balanceOf[owner]=100, totalSupply=-100, burn(150) will not revert because balance condition passes.
        bool ok;
        try c.burn(150) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok=false), bug succeeds (ok=true)
        // We assert that ok is false (reference behavior). Bug will make it true so test fails.
        assertTrue(!ok);
    }
}

