    function testRegression_property() public {
        // Mint 100 tokens to owner (address(this) is deployer/owner)
        c.mintToken(address(this), 100);
        // burn 50
        c.burn(50);
        // Reference: totalSupply = 0 (init) + 100 (mint) - 50 (burn) = 50
        // Bug: totalSupply = 0 (init) + 0 (mint bug: line missing) - 50 (burn) = -50? No, underflow revert because totalSupply is uint256
        // So reference succeeds, bug reverts because totalSupply becomes -50 underflow
        // Capture revert bool for burn(50) — actually we already called it above, so we capture totalSupply comparison
        // Better: deploy two contracts to compare? But spec says one contract c. So we check that in reference totalSupply == 50, in bug it would be 0 after mint? No, bug totalSupply stays 0 after mint, then burn(50) reverts because totalSupply -= 50 underflows.
        // So we assert that after the sequence, totalSupply is 50 (reference holds) and bug would revert — but we need one assertion. Let's do:
        // After mint(100): reference totalSupply = 100, bug totalSupply = 0.
        // Then reference burn(50) -> totalSupply = 50. Bug burn(50) reverts.
        // So we can assertTrue(c.totalSupply() == 50); which reference passes, bug fails because burn reverted earlier (so test would fail as bug's transaction reverts entirely — but Foundry test expects no revert? Actually if burn reverts, the test function reverts, so the assertion never runs -> test fails. That's correct.
        // But we need assertion that reference holds and bug breaks — if bug reverts before assertion, the test does fail. That's acceptable.
        // However, to be safe, let's do a try/catch for burn to avoid test reverting:
        bool ok;
        // Re-deploy fresh to compare both scenarios? No, one contract. 
        // Simpler: check totalSupply after mint (before burn). Reference: 100; bug: 0.
        vm.prank(address(this));
        c.burn(50);
        assertTrue(c.totalSupply() == 50);
    }
}

