pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Deploy with initialSupply=0, so owner gets 0 balance
        // Owner is msg.sender (this test contract)
        // Mint 100 tokens to owner
        c.mintToken(address(this), 100);
        // Now balanceOf[owner] = 100, totalSupply = 100
        // Call burn(50)
        // Reference: require(balanceOf[msg.sender] >= _value) => 100 >= 50 true, burn succeeds
        // Bug: require(balanceOf[msg.sender] <= _value) => 100 <= 50 false, burn reverts
        // After reference: totalSupply = 50
        // After bug: totalSupply = 100 (unchanged because revert)
        (bool ok, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", 50));
        // Only check totalSupply (not ok) because reference succeeds (ok==true) and bug reverts (ok==false)
        // But the difference we need: P.totalSupply() != M.totalSupply()
        // For reference P: burn succeeds, totalSupply = 50
        // For bug M: burn reverts, totalSupply = 100
        // So assert that totalSupply == 50 (reference) – buggy M would have 100, which fails the assert
        assertTrue(c.totalSupply() == 50);
    }
}

