        vm.prank(address(this));
        c.mintToken(nonOwner, 100);
        // Now try as nonOwner: call owned() then burn(50)
        vm.startPrank(nonOwner);
        c.owned();
        bool ok;
        try c.burn(50) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        // Reference: owned() is onlyOwner, but bug removed modifier, so burn reverts in reference but succeeds in bug
        // For the reference (correct C): ok == false because burn reverts (onlyOwner modifier on burn)
        // For the bug (modifier removed from owned): owned() doesn't set caller to owner, so burn reverts too?
        // Actually the bug only removes modifier from owned(), not from burn. burn still has onlyOwner.
        // So in both versions, burn reverts because nonOwner calls it. This divergence is not triggered.
        // Re-evaluating: The stated difference is that after burn completes, owned() differs: P.owned() != M.owned().
        // But owned() is a getter returning the owner address. After burn, owner doesn't change. So that's likely a mistake.
        // Let's correctly interpret: The only difference is owned() is callable by anyone in M. 
        // That doesn't affect burn's revert. The test must use the actual difference: the modifier removal only affects owned()'s access control.
        // Since burn still requires onlyOwner, calling burn from nonOwner reverts in both.
        // The divergence is about the revert behavior of owned() when called by nonOwner.
        // Reference: owned() reverts if msg.sender != owner.
        // Bug: owned() does NOT revert (modifier removed).
        // So we test: call owned() as nonOwner—reference reverts, bug doesn't.
        // Assert that in reference (correct) owned() reverts, in bug it doesn't.
        // But we need one concrete assertion that holds for reference and fails for bug.
        // Let's check revert bool of owned() call.
        bool success;
        try c.owned() { success = true; } catch { success = false; }
        // In reference: success == false (reverts because msg.sender != owner)
        // In bug: success == true (runs without reverting)
        assertTrue(success == false, "owned() should revert for non-owner in reference");
        // This assertion passes on reference (success == false) and fails on bug (success == true).
    }
}

