    function setUp() public { c = new C(0, "", ""); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.prank(address(this));
        c.mintToken(address(this), 100);
        vm.prank(address(this));
        c.transfer(alice, 50);
        vm.prank(address(this));
        c.burn(50);
        assertTrue(c.totalSupply() == 50);
    }
}

