pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Owner mints 1 token to self
        c.mintToken(address(this), 1);
        // Owner tries to burn 2 tokens (balance is 1, so revert expected in reference)
        // Use try/catch to capture revert
        bool burnSuccess;
        try c.burn(2) {
            burnSuccess = true;
        } catch {
            burnSuccess = false;
        }
        // After the burn call: 
        // - Reference: burn reverts, totalSupply stays 1 (1 minted, 0 burned)
        // - Buggy: burn succeeds (balanceOf[owner]=1-2 underflows to huge number, but totalSupply = 1+2? Actually burn decrements totalSupply: 1-2 underflows to huge number)
        // But simpler: just check totalSupply after the sequence
        uint256 totalSupplyAfter = c.totalSupply();
        // Reference: minted 1, burn reverted, so totalSupply = 1
        // Buggy: minted 1, burn subtracts 2 from totalSupply (1-2 = underflow to 2^256-1)
        // So reference has 1, buggy has max uint256
        assertTrue(totalSupplyAfter == 1, "totalSupply should be 1 on correct contract");
    }
}

