import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Mint 1 token to owner (msg.sender)
        c.mintToken(address(this), 1);
        // Try to burn 2 tokens; owner only has 1
        bool ok;
        try c.burn(2) { ok = true; } catch { ok = false; }
        // Reference burns revert (ok = false), totalSupply stays 1;
        // Buggy version does not revert (ok = true), totalSupply wraps/huge
        // Assert that the call reverted (reference behavior)
        assertTrue(ok == false);
    }
}

